import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MutableDateTime.addMonths
 */
public class MutableDateTime_addMonths_TriageGen0Test {

    @Test
    public void testAddMonthsPositive() {
        // Test adding a positive number of months
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        dt.addMonths(3);
        assertEquals(2023, dt.getYear());
        assertEquals(4, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsNegative() {
        // Test subtracting months using a negative integer
        MutableDateTime dt = new MutableDateTime(2023, 5, 15, 10, 0, 0, 0);
        dt.addMonths(-2);
        assertEquals(2023, dt.getYear());
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsZero() {
        // Test adding zero months
        MutableDateTime dt = new MutableDateTime(2023, 6, 15, 10, 0, 0, 0);
        dt.addMonths(0);
        assertEquals(2023, dt.getYear());
        assertEquals(6, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsYearTransition() {
        // Test adding months that cross year boundaries
        MutableDateTime dt = new MutableDateTime(2023, 11, 1, 10, 0, 0, 0);
        dt.addMonths(3);
        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsEndOfMonthEdgeCase() {
        // Test adding months where the day of the month changes due to month length (e.g., Jan 31 + 1 month -> Feb 28/29)
        MutableDateTime dt = new MutableDateTime(2023, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1);
        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        // Joda-Time handles end-of-month overflow by pinning to the last valid day
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsLeapYear() {
        // Test leap year handling
        MutableDateTime dt = new MutableDateTime(2024, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1);
        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth()); // 2024 is a leap year
    }

    @Test
    public void testAddLargeNumberOfMonths() {
        // Test adding a very large number of months
        MutableDateTime dt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        dt.addMonths(1200); // 100 years
        assertEquals(2100, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
    }
}
